-- M15.03–04, 22 original pedagogical Y1 items; based on M15 theory,
-- Drive Pedagogik mahorat 2025 and dars turlari/dars tahlili source documents.
-- Not a reproduction of historical exam questions. Production requires approval.
BEGIN;
DO $m15$
DECLARE r record; v_lesson uuid; v_con uuid; v_sub uuid; v_group text; v_qid uuid; v_oid uuid; v_choices text[]; v_n integer; v_seed text;
BEGIN
 FOR r IN SELECT * FROM (VALUES
(3,1,'O‘quvchilar maktab hovlisida daraxt ekib, tabiiy muhitni asrashni o‘rgandilar. Qaysi tarbiya?','Ekologik tarbiya — tabiatga mas’uliyatli munosabatni rivojlantirish','Estetik tarbiya — go‘zallikni idrok etishni rivojlantirish','Huquqiy tarbiya — qonun talablarini anglashni rivojlantirish','Iqtisodiy tarbiya — resursni rejalashni rivojlantirish','Maqsad tabiatni asrashga qaratilganda ekologik tarbiya ustun','qollash'),
(3,2,'O‘quvchilar boshqalarning huquqini hurmat qilish mavzusini muhokama qildilar. Yetakchi yo‘nalish?','Huquqiy tarbiya — huquq va majburiyatni anglash','Axloqiy tarbiya — xulq me’yorlariga rioya qilish','Mehnat tarbiyasi — foydali faoliyatga ko‘nikish','Estetik tarbiya — badiiy didni shakllantirish','Huquq va majburiyatlar huquqiy tarbiya mazmunidir','qollash'),
(3,3,'O‘qituvchi musiqani tinglatib san’at asaridagi go‘zallikni his etishga undadi. Bu qaysi tarbiya?','Estetik tarbiya — go‘zallikni his etish va baholash','Aqliy tarbiya — mantiqiy xulosalarni taqqoslash','Mehnat tarbiyasi — topshiriq bajarishni tashkil etish','Ekologik tarbiya — atrof-muhitni muhofaza qilish','Badiiy did va go‘zallikni anglash estetik tarbiyaga taalluqli','qollash'),
(3,4,'O‘quvchilar jamoaviy mehnatda mas’uliyat bilan vazifani tugatishdi. Yetakchi yo‘nalish?','Mehnat tarbiyasi — mehnatsevarlik va mas’uliyatni rivojlantirish','Huquqiy tarbiya — huquqiy atamalarni yod olish','Jismoniy tarbiya — faqat sport mashqlarini bajarish','Estetik tarbiya — faqat asar mazmunini baholash','Mehnatga ongli munosabat mehnat tarbiyasi vazifasidir','qollash'),
(3,5,'O‘quvchilar munozarada rostgo‘ylik va halollikni qadrlashni o‘rgandilar. Qaysi yo‘nalish?','Axloqiy tarbiya — xulq va qadriyatlarni shakllantirish','Iqtisodiy tarbiya — moliyaviy resurslardan foydalanish','Ekologik tarbiya — tabiiy resurslardan foydalanish','Jismoniy tarbiya — sog‘lom harakatlarni bajarish','Halollik va rostgo‘ylik axloqiy tarbiyaga oid','qollash'),
(3,6,'O‘quvchilarga shaxsiy budjetini oqilona rejalash o‘rgatildi. Yetakchi tarbiya turi?','Iqtisodiy tarbiya — mablag‘ni rejalash madaniyatini rivojlantirish','Axloqiy tarbiya — insonlar bilan odobli muloqot qilish','Huquqiy tarbiya — huquqiy me’yorlarga amal qilish','Estetik tarbiya — san’atni tushunish va qadrlash','Resursni rejalash iqtisodiy tarbiya maqsadi','qollash'),
(3,7,'Tarbiya metodi bilan tarbiya yo‘nalishi nimasi bilan farqlanadi?','Metod ta’sir yo‘li, yo‘nalish esa tarbiyaviy maqsad mazmunidir','Metod tarbiya natijasi, yo‘nalish esa faqat baho qo‘yishdir','Metod faqat sport mashqi, yo‘nalish esa dars jadvalidir','Metod faqat eslatma, yo‘nalish esa sinf jurnalidir','Ishontirish metod, axloqiy tarbiya esa yo‘nalish misolidir','bilish'),
(3,8,'O‘qituvchi o‘z odobi bilan o‘quvchilarga ibrat ko‘rsatdi. Qaysi metoddan foydalandi?','Shaxsiy namuna ko‘rsatish orqali tarbiyaviy ta’sir etdi','Faqat ma’muriy jazoni qo‘llash orqali ta’sir etdi','Faqat yakuniy baholash orqali tarbiyaviy ta’sir etdi','Faqat axborotni nusxalash orqali tarbiyaviy ta’sir etdi','Ijobiy shaxsiy namuna tarbiyaviy metod bo‘la oladi','qollash'),
(3,9,'O‘quvchining foydali ishiga asosli e’tirof bildirildi. Qaysi tarbiya metodi?','Rag‘batlantirish — ijobiy faoliyatni qo‘llab-quvvatlash','Ishontirish — dalil bilan fikrga ta’sir etish','Mashq qildirish — faoliyatni muntazam takrorlash','Talab qo‘yish — xatti-harakat me’yorini belgilash','Ijobiy natijani e’tirof etish rag‘batlantirishdir','bilish'),
(3,10,'Nima uchun tarbiyaviy vaziyatni faqat jazo bilan hal qilish yetarli emas?','Xulq sababini tushunib, ijobiy yo‘l ko‘rsatish zarur','Jazo har qanday vaziyatda tushunishni avtomatik yaratadi','Bitta jazo o‘quvchi ehtiyojlarini to‘liq bartaraf qiladi','Faqat jazolash barcha tarbiya metodlari o‘rnini bosadi','Tarbiya maqsadga muvofiq turli metodlar uyg‘unligini talab qiladi','mulohaza'),
(3,11,'O‘quvchi ekologik loyihada ham jamoa bilan ishlab, ham tabiatni muhofaza qildi. Xulosa?','Bitta faoliyat bir nechta tarbiyaviy yo‘nalishga xizmat qilishi mumkin','Har bir faoliyat faqat bitta qat’iy tarbiya turidan iborat bo‘ladi','Tarbiya yo‘nalishlari o‘zaro bog‘lanishi hech qachon mumkin emas','Jamoaviy ish tarbiyaviy maqsadga umuman ta’sir ko‘rsatmaydi','Tarbiya yo‘nalishlari amaliy faoliyatda birgalikda yuzaga chiqadi','mulohaza'),
(3,12,'O‘qituvchi o‘quvchiga axloqiy tanlov sabablarini dalil bilan izohladi. Qaysi metod yetakchi?','Ishontirish — dalil va tushuntirish bilan ta’sir qilish','Rag‘batlantirish — foydali harakatni munosib e’tirof etish','Mashq qildirish — kerakli harakatni muntazam qaytarish','Jamoa tashkil etish — vazifalarni guruhlarga taqsimlash','Dalilli tushuntirish ishontirish metodining namunasidir','qollash'),
(4,1,'Yangi tushunchani ilk bor bayon etish darsning asosiy maqsadi. Qaysi dars turi?','Yangi bilim darsi — tushunchani dastlab shakllantirish','Mustahkamlash darsi — o‘tgan bilimni takrorlash','Nazorat darsi — o‘zlashtirish darajasini tekshirish','Umumlashtirish darsi — bilimlarni tizimga keltirish','Dars turini yetakchi didaktik maqsad belgilaydi','bilish'),
(4,2,'O‘quvchilar ilgari o‘tilgan qoidalarni mashqlar orqali qayta qo‘lladilar. Bu qanday dars?','Mustahkamlash va takrorlash darsi — bilimni mashq qilish','Yangi bilim darsi — mavzuni ilk bor tushuntirish','Nazorat darsi — yakuniy natijani baholash','Ekskursiya darsi — tashqi obyektni kuzatish','Avval o‘rganilgan bilimni mashq qilish mustahkamlashga xos','qollash'),
(4,3,'Bir darsda so‘rov, yangi tushuntirish va mashq bo‘ldi. Dars turi qanday?','Aralash dars — bir necha didaktik vazifa uyg‘unlashadi','Nazorat darsi — faqat bilimni tekshirish ustun bo‘ladi','Laboratoriya darsi — tajriba o‘tkazish ustun bo‘ladi','Ekskursiya darsi — tashrif va kuzatish ustun bo‘ladi','Aralash dars bir nechta bosqichni birlashtiradi','bilish'),
(4,4,'O‘quvchilar turli mavzudagi bilimlarni sxemaga yig‘ib, aloqalarini topdilar. Qaysi dars?','Umumlashtirish va tizimlashtirish darsi — bilimlarni bog‘lash','Yangi bilim berish darsi — bir tushunchani ilk bor berish','Nazorat darsi — natijalarni test bilan baholash','Laboratoriya darsi — tajriba sharoitida kuzatish','Tizimlashtirish bilimlararo bog‘lanishni umumlashtiradi','qollash'),
(4,5,'O‘qituvchi dars mazmuni fanga mos va izchil berilganini o‘rganmoqda. Qaysi tahlil?','Didaktik tahlil — mazmun va ta’limning maqsadga muvofiqligi','Psixologik tahlil — sinfning ruhiy va emotsional muhiti','Uslubiy tahlil — qo‘llangan metodlarning natijadorligi','Tashkiliy tahlil — dars vaqtining taqsimlanish tartibi','Didaktik tahlil dars mazmuni va o‘qitish sifatini tekshiradi','qollash'),
(4,6,'Darsda qo‘llangan guruhlash metodining mosligi muhokama qilindi. Qaysi tahlil?','Uslubiy tahlil — tanlangan metod va usullarning samarasi','Psixologik tahlil — diqqat va hissiy holatning o‘zgarishi','Didaktik tahlil — o‘quv mazmunining ilmiyligi','Tashkiliy tahlil — darsning vaqt jadvaliga mosligi','Metod tanloviga uslubiy tahlil aloqador','qollash'),
(4,7,'O‘quvchilarning xavotiri va diqqat taqsimoti dars davomida baholandi. Qaysi tahlil?','Psixologik tahlil — diqqat va ruhiy muhit','Uslubiy tahlil — ko‘rgazmali vositani tanlash','Didaktik tahlil — tushunchaning ilmiy aniqligi','Metodologik tahlil — nazariy yondashuv asoslari','Psixologik tahlil o‘quvchining ruhiy faoliyatini o‘rganadi','qollash'),
(4,8,'Sinfda vaqt yetmay qoldi, mashq uchun reja buzildi. Eng samarali yondashuv?','Bosqichlar vaqtini qayta rejalab, ustuvor maqsadni saqlash','Nazoratni butunlay bekor qilib, sababni tekshirmaslik','Topshiriqni o‘zgartirmasdan barcha o‘quvchilarni shoshirish','Sinfdagi o‘rganish farqlarini butunlay e’tiborsiz qoldirish','Vaqtni boshqarish sinf boshqaruvining muhim jihatidir','mulohaza'),
(4,9,'Barcha faoliyatlar faqat bir necha faol o‘quvchi bilan kechdi. Qanday tuzatish kerak?','Guruh rollarini teng taqsimlab, barchaning ishtirokini kuzatish','Faqat faol o‘quvchilar uchun yangi vazifalar ajratish','Qolgan o‘quvchilarni doimiy ravishda kuzatuvchi qilib qo‘yish','Faoliyatni natijani tekshirmay bir xil tarkibda davom ettirish','Sinf boshqaruvi har bir o‘quvchi ishtirokini ko‘zda tutadi','mulohaza'),
(4,10,'Nazorat ishidan keyin o‘qituvchi xatolarni aniqlab keyingi mashqni rejaladi. Qaysi bosqichlar ketma-ket?','Baholash, tahlil va o‘qitishni moslashtirish ketma-ketligi','Faqat baholash, mukofot va topshiriqni tugatish ketma-ketligi','Faqat darslik tanlash, nusxa olish va ball qo‘yish ketma-ketligi','Faqat ta’rif yozish, tanbeh berish va guruhlash ketma-ketligi','Nazorat natijasi keyingi pedagogik rejalash uchun ishlatiladi','mulohaza')
 ) t(topic_order,seed_no,stem,answer,wrong_1,wrong_2,wrong_3,explanation,cognitive)
 LOOP
  SELECT l.id INTO STRICT v_lesson FROM public.lessons l JOIN public.modules m ON m.id=l.module_id WHERE m.code='M15' AND l.order_idx=r.topic_order AND l.status='published';
  SELECT c.id,c.subject_id,c.group_code INTO STRICT v_con,v_sub,v_group FROM public.constructs c WHERE c.code='PM.GEN.'||lpad(r.topic_order::text,2,'0') AND c.is_active;
  v_seed := 'm15-y1-20261018:'||r.topic_order::text||':'||r.seed_no::text;
  v_qid := md5(v_seed)::uuid;
  INSERT INTO public.questions (id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,source_reference,source_lesson_id,is_generated)
  VALUES(v_qid,v_sub,v_con,v_group,'Y1'::public.question_format,r.cognitive::public.cognitive_level,3,r.stem,'review'::public.content_status,'authored:m15-topictest-20261018:'||r.topic_order::text||':'||r.seed_no::text,v_lesson,false)
  ON CONFLICT (id) DO NOTHING;
  v_choices := ARRAY[r.answer,r.wrong_1,r.wrong_2,r.wrong_3];
  FOR v_n IN 1..4 LOOP
    v_oid := md5(v_seed||':option:'||v_n::text)::uuid;
    INSERT INTO public.question_options(id,question_id,side,order_idx,content_md) VALUES(v_oid,v_qid,'a',v_n,v_choices[v_n]) ON CONFLICT(id) DO NOTHING;
  END LOOP;
  INSERT INTO public.question_keys(question_id,payload,explanation_md)
  VALUES(v_qid,jsonb_build_object('correct_option_id',md5(v_seed||':option:1')::uuid),r.explanation)
  ON CONFLICT(question_id) DO NOTHING;
 END LOOP;
END
$m15$;
COMMIT;